/// SYNTHETIC demo data (spec 8.9), generated by backend/scripts/make_demo_data.py and
/// bundled as an asset. Every record is stored with origin = demo.
library;

import 'dart:convert';

import 'models.dart';

class DemoDataset {
  const DemoDataset({required this.bills, required this.production, required this.anomalyMonths});
  final List<Bill> bills;
  final List<(String, double)> production;
  final List<String> anomalyMonths;
}

DemoDataset parseDemoData(String jsonText, {required String Function() newId, DateTime? now}) {
  final data = jsonDecode(jsonText) as Map<String, dynamic>;
  if (data['synthetic'] != true) throw const FormatException('demo data must be marked synthetic');
  final t = now ?? DateTime.now();
  final bills = <Bill>[];
  final production = <(String, double)>[];
  Bill make(String month, BillType type, double qty, EnergyUnit unit, double amount) => Bill(
        id: newId(),
        billType: type,
        billingMonth: month,
        consumedUnits: qty,
        unit: unit,
        origin: DataOrigin.demo,
        confirmedAt: t,
        createdAt: t,
        updatedAt: t,
        totalAmountBdt: amount,
        utilityName: 'SYNTHETIC',
      );
  for (final raw in data['months'] as List<dynamic>) {
    final m = raw as Map<String, dynamic>;
    final month = m['month'] as String;
    double d(String k) => (m[k] as num).toDouble();
    bills
      ..add(make(month, BillType.electricity, d('electricity_kwh'), EnergyUnit.kWh, d('electricity_cost_bdt')))
      ..add(make(month, BillType.diesel, d('diesel_litres'), EnergyUnit.litre, d('diesel_cost_bdt')))
      ..add(make(month, BillType.gas, d('gas_m3'), EnergyUnit.m3, d('gas_cost_bdt')));
    production.add((month, d('production_units')));
  }
  return DemoDataset(
    bills: bills,
    production: production,
    anomalyMonths: (data['anomaly_months'] as List<dynamic>).cast<String>(),
  );
}
